import{_ as e,o as a,c as o,ag as r}from"./chunks/framework.KxDd3USm.js";const p=JSON.parse('{"title":"11 专业英语","description":"","frontmatter":{},"headers":[],"relativePath":"11-专业英语/index.md","filePath":"11-专业英语/index.md"}'),i={name:"11-专业英语/index.md"};function n(d,t,l,c,s,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="_11-专业英语" tabindex="-1">11 专业英语 <a class="header-anchor" href="#_11-专业英语" aria-label="Permalink to &quot;11 专业英语&quot;">​</a></h1><blockquote><p><strong>分值地位</strong>：基础知识第 71–75 题通常固定为一篇 IT 主题英文短文、5 个完形填空，共 <strong>5 分（约占上午卷 6.67%）</strong>。它不单独对应下午案例大题，但题号固定、选项明确，是很值得争取的稳定分。</p><p><strong>学习目标</strong>：学完本课后，你能——① 不逐字翻译也能快速判断短文主题；② 用“词性—搭配—逻辑—专业知识”四层筛选选项；③ 掌握软件工程、数据库、网络安全、云计算和 AI 的高频词；④ 避开 <code>actual</code>、<code>execute</code>、<code>library</code>、<code>argument</code> 等“看着眼熟却容易译错”的词；⑤ 在 5–7 分钟内完成一组 5 空专业英语题，并说出每个答案的文本依据。</p></blockquote><hr><h2 id="第一部分-本课导航" tabindex="-1">第一部分 本课导航 <a class="header-anchor" href="#第一部分-本课导航" aria-label="Permalink to &quot;第一部分 本课导航&quot;">​</a></h2><h3 id="_1-本章究竟考什么" tabindex="-1">1. 本章究竟考什么 <a class="header-anchor" href="#_1-本章究竟考什么" aria-label="Permalink to &quot;1. 本章究竟考什么&quot;">​</a></h3><p>专业英语不是单独考语法，也不是要求翻译整篇文章。它把三种能力揉在一起：</p><ol><li><strong>专业知识</strong>：知道 requirement、transaction、encryption、scalability 等概念；</li><li><strong>英文搭配</strong>：知道 <code>comply with</code>、<code>be responsible for</code>、<code>rather than</code> 怎样搭配；</li><li><strong>上下文推理</strong>：能根据因果、转折、同义复现判断空格含义。</li></ol><p>常见主题包括：软件工程与测试、面向对象与设计模式、数据结构与数据库、操作系统与网络、信息安全，以及 cloud、AI、machine learning 等新技术。</p><h3 id="_2-本章与已有课程的联动" tabindex="-1">2. 本章与已有课程的联动 <a class="header-anchor" href="#_2-本章与已有课程的联动" aria-label="Permalink to &quot;2. 本章与已有课程的联动&quot;">​</a></h3><p>英文题常常只是把你学过的中文结论换一种语言表达。例如：</p><ul><li><code>high cohesion and low coupling</code> = 高内聚、低耦合；</li><li><code>a transaction is atomic</code> = 事务具有原子性；</li><li><code>only Load/Store instructions access memory</code> = 只有 Load/Store 指令访存；</li><li><code>a digital signature provides authentication and non-repudiation</code> = 数字签名提供身份认证和不可否认性。</li></ul><p>所以专业英语的本质是：<strong>用英文识别熟悉的计算机知识</strong>，不需要把自己训练成文学翻译。</p><h3 id="_3-建议得分目标与时间" tabindex="-1">3. 建议得分目标与时间 <a class="header-anchor" href="#_3-建议得分目标与时间" aria-label="Permalink to &quot;3. 建议得分目标与时间&quot;">​</a></h3><table tabindex="0"><thead><tr><th>当前基础</th><th style="text-align:right;">第一目标</th><th style="text-align:right;">做题时间</th></tr></thead><tbody><tr><td>英语较弱</td><td style="text-align:right;">先保 3/5</td><td style="text-align:right;">7 分钟内</td></tr><tr><td>一般</td><td style="text-align:right;">稳定 4/5</td><td style="text-align:right;">5–6 分钟</td></tr><tr><td>较好</td><td style="text-align:right;">冲 5/5</td><td style="text-align:right;">4–5 分钟</td></tr></tbody></table><p>做题顺序：先读本章解题法和词汇表，再做 3 篇课后完形，最后限时做精华题。</p><hr>',16)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
